/* ===================== BÀI 44 · Thiết kế driver tái sử dụng ===================== */
/* Bài 44 · Thiết kế driver tái sử dụng (AMTS-EMB-001-M11-L04, MC51-044) — sinh bởi tools/author/mcu8051/l44.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const PR44=[{"label":"Ví dụ: Ba lớp, driver OUT8 cho 74HC595","code":"; Ví dụ 1: ứng dụng -> driver OUT8 -> bus SPI (74HC595)\n; Nối dây giả định; đổi chân chỉ sửa 4 dòng BIT dưới đây.\nSCK     BIT     P1.4\nMOSI    BIT     P1.5\nMISO    BIT     P1.6\nCS595   BIT     P1.7                    ; nối chân RCLK của 74HC595\n        ORG     0000H\n        SJMP    MAIN\n; ===== LỚP BUS: SPI_XFER (mode 0, bit 7 trước) =====\n; Vào A = byte gửi. Ra A = byte nhận. Phá R7.\nSPI_XFER:\n        MOV     R7,#8\nSX:     RLC     A\n        MOV     MOSI,C\n        SETB    SCK\n        MOV     C,MISO\n        CLR     SCK\n        MOV     ACC.0,C\n        DJNZ    R7,SX\n        RET\n; ===== LỚP DRIVER: OUT8 = 8 đèn, logic dương =====\n; OUT8_INIT: bus về trạng thái nghỉ.\n; OUT8_WRITE: vào A (bit = 1: đèn sáng); ra CY = 0 (ghi\n; được; 74HC595 không trả lời nên không báo lỗi). Phá A, R7.\nOUT8_INIT:\n        CLR     SCK\n        SETB    CS595\n        RET\nOUT8_WRITE:\n        CLR     CS595\n        LCALL   SPI_XFER\n        SETB    CS595                   ; sườn lên RCLK: chốt ra 8 chân\n        CLR     C\n        RET\n; ===== LỚP ỨNG DỤNG: không biết đèn nối qua bus nào =====\nMAIN:   LCALL   OUT8_INIT\n        MOV     A,#3CH                  ; bật 4 đèn giữa\n        LCALL   OUT8_WRITE\n        CLR     A\n        RLC     A\n        MOV     30H,A                   ; 00H: ghi được, 01H: lỗi\n        SJMP    $\n        END\n","note":"Ứng dụng gọi OUT8_INIT, OUT8_WRITE với A = 3CH; driver gọi bus SPI. 74HC595 chốt 3CH: 4 đèn giữa sáng. 104 chu kỳ máy. Tên chân đặt bằng BIT, mã máy giống hệt khi viết P1.4.","dev":{"spi":{"devs":[{"type":"hc595"}]}},"fosc":12000000},{"label":"Ví dụ: Cùng ứng dụng, driver cho PCF8574","code":"; Ví dụ 2: CÙNG ứng dụng, driver OUT8 cho PCF8574 (I2C)\n; Nối dây giả định. PCF8574 ở địa chỉ 20H, đèn sáng khi\n; chân = 0 (giả định) -> driver đảo bit, ứng dụng không biết.\nSDA     BIT     P1.0\nSCL     BIT     P1.1\nPCF_W   EQU     40H                     ; địa chỉ 20H + bit ghi (0)\n        ORG     0000H\n        SJMP    MAIN\n; ===== LỚP BUS: I2C (Bài 41) =====\nI2C_START:\n        SETB    SDA\n        SETB    SCL\n        CLR     SDA\n        CLR     SCL\n        RET\nI2C_STOP:                               ; không đổi CY\n        CLR     SDA\n        SETB    SCL\n        SETB    SDA\n        RET\nI2C_WRITE:                              ; gửi A; CY = 1 nếu NACK. Phá R7\n        MOV     R7,#8\nWB:     RLC     A\n        MOV     SDA,C\n        SETB    SCL\n        CLR     SCL\n        DJNZ    R7,WB\n        SETB    SDA\n        SETB    SCL\n        MOV     C,SDA\n        CLR     SCL\n        RET\n; ===== LỚP DRIVER: OUT8, cùng giao diện với ví dụ 1 =====\n; Vào A (bit = 1: đèn sáng); ra CY = 1 nếu chip không\n; trả lời. Phá A, R6, R7.\nOUT8_INIT:\n        SETB    SDA\n        SETB    SCL\n        RET\nOUT8_WRITE:\n        CPL     A                       ; logic dương -> mức chân\n        MOV     R6,A\n        LCALL   I2C_START\n        MOV     A,#PCF_W\n        LCALL   I2C_WRITE\n        JC      O8_END                  ; NACK: không gửi dữ liệu\n        MOV     A,R6\n        LCALL   I2C_WRITE\nO8_END: LCALL   I2C_STOP\n        RET\n; ===== LỚP ỨNG DỤNG: giống hệt ví dụ 1 =====\nMAIN:   LCALL   OUT8_INIT\n        MOV     A,#3CH                  ; bật 4 đèn giữa\n        LCALL   OUT8_WRITE\n        CLR     A\n        RLC     A\n        MOV     30H,A                   ; 00H: ghi được, 01H: lỗi\n        SJMP    $\n        END\n","note":"Phần ứng dụng giống từng byte với ví dụ 1. Driver đảo bit (3CH → C3H) rồi gửi qua I2C: “S 40 ACK C3 ACK P”. Đèn sáng giống ví dụ 1. 167 chu kỳ.","dev":{"i2c":{"devs":[{"type":"pcf8574","addr":32}]}},"fosc":12000000},{"label":"Lỗi: Chip ở địa chỉ 21H, driver báo CY = 1","code":"; Ví dụ 3 (lỗi): chip PCF8574 trên bo ở địa chỉ 21H (A0 = 1),\n; driver vẫn gọi 20H. Code giống hệt ví dụ 2: driver báo\n; CY = 1, ứng dụng ghi 30H = 01H và không bị treo.\nSDA     BIT     P1.0\nSCL     BIT     P1.1\nPCF_W   EQU     40H                     ; địa chỉ 20H + bit ghi (0)\n        ORG     0000H\n        SJMP    MAIN\n; ===== LỚP BUS: I2C (Bài 41) =====\nI2C_START:\n        SETB    SDA\n        SETB    SCL\n        CLR     SDA\n        CLR     SCL\n        RET\nI2C_STOP:                               ; không đổi CY\n        CLR     SDA\n        SETB    SCL\n        SETB    SDA\n        RET\nI2C_WRITE:                              ; gửi A; CY = 1 nếu NACK. Phá R7\n        MOV     R7,#8\nWB:     RLC     A\n        MOV     SDA,C\n        SETB    SCL\n        CLR     SCL\n        DJNZ    R7,WB\n        SETB    SDA\n        SETB    SCL\n        MOV     C,SDA\n        CLR     SCL\n        RET\n; ===== LỚP DRIVER: OUT8, cùng giao diện với ví dụ 1 =====\n; Vào A (bit = 1: đèn sáng); ra CY = 1 nếu chip không\n; trả lời. Phá A, R6, R7.\nOUT8_INIT:\n        SETB    SDA\n        SETB    SCL\n        RET\nOUT8_WRITE:\n        CPL     A                       ; logic dương -> mức chân\n        MOV     R6,A\n        LCALL   I2C_START\n        MOV     A,#PCF_W\n        LCALL   I2C_WRITE\n        JC      O8_END                  ; NACK: không gửi dữ liệu\n        MOV     A,R6\n        LCALL   I2C_WRITE\nO8_END: LCALL   I2C_STOP\n        RET\n; ===== LỚP ỨNG DỤNG: giống hệt ví dụ 1 =====\nMAIN:   LCALL   OUT8_INIT\n        MOV     A,#3CH                  ; bật 4 đèn giữa\n        LCALL   OUT8_WRITE\n        CLR     A\n        RLC     A\n        MOV     30H,A                   ; 00H: ghi được, 01H: lỗi\n        SJMP    $\n        END\n","note":"Code giống ví dụ 2, nhưng chip trên bo ở địa chỉ 21H: “S 40 NACK P”. Driver dừng sau byte địa chỉ, trả CY = 1; ứng dụng ghi 30H = 01H và không bị treo. 101 chu kỳ.","dev":{"i2c":{"devs":[{"type":"pcf8574","addr":33}]}},"fosc":12000000},{"label":"Bẫy: Driver phá R7 của ứng dụng","code":"; Ví dụ 4 (bẫy): ứng dụng giữ mẫu đèn trong R7, driver\n; cũng dùng R7 -> đèn hiện 01, 00, 00 thay vì 01, 02, 04.\nSCK     BIT     P1.4\nMOSI    BIT     P1.5\nMISO    BIT     P1.6\nCS595   BIT     P1.7\n        ORG     0000H\n        SJMP    MAIN\nSPI_XFER:                               ; phá R7\n        MOV     R7,#8\nSX:     RLC     A\n        MOV     MOSI,C\n        SETB    SCK\n        MOV     C,MISO\n        CLR     SCK\n        MOV     ACC.0,C\n        DJNZ    R7,SX\n        RET\nOUT8_INIT:\n        CLR     SCK\n        SETB    CS595\n        RET\nOUT8_WRITE:                             ; ghi chú hợp đồng: \"phá A, R7\"\n        CLR     CS595\n        LCALL   SPI_XFER\n        SETB    CS595\n        CLR     C\n        RET\n; ===== ỨNG DỤNG: đèn chạy 3 bước 01H, 02H, 04H =====\nMAIN:   LCALL   OUT8_INIT\n        MOV     R2,#3                   ; số bước\n        MOV     R7,#01H                 ; BẪY: mẫu đèn trong R7 (driver phá)\nLAP:    MOV     A,R7\n        LCALL   OUT8_WRITE\n        MOV     A,R7\n        RL      A                       ; đèn kế tiếp\n        MOV     R7,A\n        DJNZ    R2,LAP\n        SJMP    $\n        END\n","note":"Đoán trước: ba lần gọi hiện mẫu nào? Ứng dụng muốn 01, 02, 04 nhưng driver trả R7 = 0 nên hiện 01, 00, 00. Xem R7 sau lần gọi đầu.","dev":{"spi":{"devs":[{"type":"hc595"}]}},"fosc":12000000},{"label":"Ví dụ: Driver giữ R7 bằng PUSH/POP","code":"; Ví dụ 5: sửa ví dụ 4 trong DRIVER, không sửa ứng dụng:\n; OUT8_WRITE cất R7 lên ngăn xếp rồi lấy lại.\nSCK     BIT     P1.4\nMOSI    BIT     P1.5\nMISO    BIT     P1.6\nCS595   BIT     P1.7\n        ORG     0000H\n        SJMP    MAIN\nSPI_XFER:                               ; phá R7\n        MOV     R7,#8\nSX:     RLC     A\n        MOV     MOSI,C\n        SETB    SCK\n        MOV     C,MISO\n        CLR     SCK\n        MOV     ACC.0,C\n        DJNZ    R7,SX\n        RET\nOUT8_INIT:\n        CLR     SCK\n        SETB    CS595\n        RET\nOUT8_WRITE:                             ; hợp đồng mới: chỉ phá A\n        PUSH    07H                     ; R7 của bank 0 ở địa chỉ 07H\n        CLR     CS595\n        LCALL   SPI_XFER\n        SETB    CS595\n        POP     07H\n        CLR     C\n        RET\n; ===== ỨNG DỤNG: giữ nguyên như ví dụ 4 =====\nMAIN:   LCALL   OUT8_INIT\n        MOV     R2,#3                   ; số bước\n        MOV     R7,#01H                 ; mẫu đèn trong R7 (driver giữ)\nLAP:    MOV     A,R7\n        LCALL   OUT8_WRITE\n        MOV     A,R7\n        RL      A                       ; đèn kế tiếp\n        MOV     R7,A\n        DJNZ    R2,LAP\n        SJMP    $\n        END\n","note":"Driver cất R7 (PUSH 07H … POP 07H), ứng dụng không đổi: hiện đúng 01, 02, 04. Mỗi lần gọi thêm 4 chu kỳ (316 so với 304).","dev":{"spi":{"devs":[{"type":"hc595"}]}},"fosc":12000000}];
const sim44=makeSim51(document.getElementById("m51-l44"),{id:"s44",presets:PR44,ram:256});
makeEx51(document.getElementById("ex-l44"),"l44",[{"t":"Driver 4 đèn giữ đúng hợp đồng","d":"<p>Bo có 4 đèn ở <code>P2.0<\/code>–<code>P2.3<\/code>, đèn sáng khi chân = 0 (giả định); <code>P2.4<\/code>–<code>P2.7<\/code> đang được phần khác của chương trình dùng. Hợp đồng của hàm <code>LED_WRITE<\/code>: vào A, bit 3…0 = 1 nghĩa là đèn tương ứng sáng (logic dương, bit 7…4 bỏ qua); hàm chỉ được đổi A, CY và 4 bit thấp của P2; phải giữ nguyên <code>R0<\/code>–<code>R7<\/code> và 4 bit cao của P2. Code mẫu sai hợp đồng ở hai chỗ. Sửa <code>LED_WRITE<\/code>, không sửa phần ứng dụng (ứng dụng đặt P2 = <code>31H<\/code> rồi gọi hàm với A = <code>30H<\/code>).<\/p><p>Ví dụ: <code>30H = 05H<\/code>, P2 lúc gọi = <code>A0H<\/code> → P2 = <code>AAH<\/code> (đèn 0 và 2 sáng, P2.7…4 vẫn 1010), R0–R7 không đổi.<\/p>","start":"; Đèn 0..3 ở P2.0..P2.3, sáng khi chân = 0 (giả định).\n; P2.7..P2.4 đang dùng cho việc khác: không được đổi.\n; Hợp đồng LED_WRITE: vào A (bit 3..0 = 1: đèn sáng); chỉ\n; được đổi A, CY và P2.3..P2.0; giữ nguyên R0..R7.\n        ORG     0000H\n        SJMP    MAIN\nLED_WRITE:\n        MOV     R7,A                    ; SAI: phá R7 của ứng dụng\n        CPL     A\n        MOV     P2,A                    ; SAI: ghi đè cả P2.7..P2.4\n        RET\n; ---- Ứng dụng (đừng sửa) ----\nMAIN:   MOV     P2,31H                  ; trạng thái cổng lúc gọi driver\n        MOV     A,30H\n        LCALL   LED_WRITE\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x00":18,"0x01":35,"0x02":52,"0x03":69,"0x04":86,"0x05":103,"0x06":120,"0x07":137,"0x30":5,"0x31":160}},"expect":{"iram":{"0x00":18,"0x01":35,"0x02":52,"0x03":69,"0x04":86,"0x05":103,"0x06":120,"0x07":137,"0x30":5},"ports":{"P2":170}}},{"setup":{"iram":{"0x00":19,"0x01":36,"0x02":53,"0x03":70,"0x04":87,"0x05":104,"0x06":121,"0x07":138,"0x30":0,"0x31":255}},"expect":{"iram":{"0x00":19,"0x01":36,"0x02":53,"0x03":70,"0x04":87,"0x05":104,"0x06":121,"0x07":138,"0x30":0},"ports":{"P2":255}}},{"setup":{"iram":{"0x00":20,"0x01":37,"0x02":54,"0x03":71,"0x04":88,"0x05":105,"0x06":122,"0x07":139,"0x30":15,"0x31":95}},"expect":{"iram":{"0x00":20,"0x01":37,"0x02":54,"0x03":71,"0x04":88,"0x05":105,"0x06":122,"0x07":139,"0x30":15},"ports":{"P2":80}}},{"setup":{"iram":{"0x00":21,"0x01":38,"0x02":55,"0x03":72,"0x04":89,"0x05":106,"0x06":123,"0x07":140,"0x30":243,"0x31":48}},"expect":{"iram":{"0x00":21,"0x01":38,"0x02":55,"0x03":72,"0x04":89,"0x05":106,"0x06":123,"0x07":140,"0x30":243},"ports":{"P2":60}}},{"setup":{"iram":{"0x00":22,"0x01":39,"0x02":56,"0x03":73,"0x04":90,"0x05":107,"0x06":124,"0x07":141,"0x30":8,"0x31":0}},"expect":{"iram":{"0x00":22,"0x01":39,"0x02":56,"0x03":73,"0x04":90,"0x05":107,"0x06":124,"0x07":141,"0x30":8},"ports":{"P2":7}}},{"setup":{"iram":{"0x00":23,"0x01":40,"0x02":57,"0x03":74,"0x04":91,"0x05":108,"0x06":125,"0x07":142,"0x30":10,"0x31":201}},"expect":{"iram":{"0x00":23,"0x01":40,"0x02":57,"0x03":74,"0x04":91,"0x05":108,"0x06":125,"0x07":142,"0x30":10},"ports":{"P2":197}}}]},"hints":["Đổi logic dương thành mức chân bằng CPL A. Không cần thanh ghi tạm nào ngoài A.","Lệnh đọc–sửa–ghi trên cổng (ORL P2,…, ANL P2,…) đọc CHỐT của cổng, đổi đúng các bit cần đổi, giữ các bit khác.","Hai lệnh đọc–sửa–ghi trên P2: một lệnh tắt cả 4 đèn, một lệnh AND với một byte có 4 bit cao bằng 1."],"why":"Hợp đồng (vào gì, ra gì, được phá thanh ghi nào, chạm phần cứng nào) là thứ giúp ứng dụng gọi driver mà không cần đọc ruột driver. Driver phá R7 hay ghi đè cả cổng sẽ gây lỗi ở chỗ khác, rất khó tìm (ví dụ 4). Cách ORL rồi ANL làm đèn tắt rất ngắn (1 chu kỳ) giữa hai lệnh nhưng không bao giờ bật nhầm đèn; muốn đổi trong một lần ghi thì phải đọc chốt vào A trước (cần thêm một chỗ tạm)."},{"t":"Chọn driver lúc chạy bằng bảng nhảy","d":"<p>Ba driver <code>DRV0<\/code>, <code>DRV1<\/code>, <code>DRV2<\/code> có cùng giao diện (vào A = mẫu đèn, ra CY = 0) nhưng điều khiển ba “thiết bị” khác nhau: thiết bị 0 ghi thẳng ra P1, thiết bị 1 ghi mẫu đảo ra P2, thiết bị 2 ghi vào ô <code>40H<\/code>. Viết hàm <code>OUT8<\/code>: đọc số thiết bị ở <code>30H<\/code>; nếu 0–2 thì chạy driver tương ứng với đúng mẫu đèn trong A; nếu <code>30H<\/code> ≥ 3 thì không gọi driver nào, trả về CY = 1. Ứng dụng (đừng sửa) gọi <code>OUT8<\/code> với A = <code>31H<\/code> rồi ghi CY vào <code>32H<\/code>. Không đổi <code>30H<\/code>, <code>31H<\/code>.<\/p><p>Ví dụ: <code>30H = 01H<\/code>, <code>31H = 5AH<\/code> → P2 = <code>A5H<\/code>, P1 = <code>FFH<\/code>, <code>32H = 00H<\/code>.<\/p>","start":"; Ba driver cùng giao diện: vào A = mẫu đèn, ra CY = 0.\n; OUT8 chọn driver theo số thiết bị ở 30H (0, 1, 2);\n; 30H >= 3: không gọi driver nào, ra CY = 1.\n        ORG     0000H\n        SJMP    MAIN\nDRV0:   MOV     P1,A                    ; thiết bị 0: đèn trực tiếp trên P1\n        CLR     C\n        RET\nDRV1:   CPL     A                       ; thiết bị 1: P2, sáng khi chân = 0\n        MOV     P2,A\n        CLR     C\n        RET\nDRV2:   MOV     40H,A                   ; thiết bị 2: ghi nhật ký vào RAM\n        CLR     C\n        RET\nOUT8:   MOV     R2,A\n        MOV     A,30H\n        CJNE    A,#0,O1\n        MOV     A,R2\n        SJMP    DRV0\nO1:     MOV     A,R2                    ; TODO: thiết bị 2 và báo lỗi\n        SJMP    DRV1\n; ---- Ứng dụng (đừng sửa) ----\nMAIN:   MOV     A,31H\n        LCALL   OUT8\n        CLR     A\n        RLC     A\n        MOV     32H,A                   ; 00H: được, 01H: không có thiết bị\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x30":1,"0x31":90,"0x32":238,"0x40":238}},"expect":{"iram":{"0x30":1,"0x31":90,"0x32":0,"0x40":238},"ports":{"P1":255,"P2":165}}},{"setup":{"iram":{"0x30":0,"0x31":90,"0x32":238,"0x40":238}},"expect":{"iram":{"0x30":0,"0x31":90,"0x32":0,"0x40":238},"ports":{"P1":90,"P2":255}}},{"setup":{"iram":{"0x30":2,"0x31":90,"0x32":238,"0x40":238}},"expect":{"iram":{"0x30":2,"0x31":90,"0x32":0,"0x40":90},"ports":{"P1":255,"P2":255}}},{"setup":{"iram":{"0x30":3,"0x31":90,"0x32":238,"0x40":238}},"expect":{"iram":{"0x30":3,"0x31":90,"0x32":1,"0x40":238},"ports":{"P1":255,"P2":255}}},{"setup":{"iram":{"0x30":255,"0x31":90,"0x32":238,"0x40":238}},"expect":{"iram":{"0x30":255,"0x31":90,"0x32":1,"0x40":238},"ports":{"P1":255,"P2":255}}},{"setup":{"iram":{"0x30":0,"0x31":129,"0x32":238,"0x40":238}},"expect":{"iram":{"0x30":0,"0x31":129,"0x32":0,"0x40":238},"ports":{"P1":129,"P2":255}}},{"setup":{"iram":{"0x30":2,"0x31":0,"0x32":238,"0x40":238}},"expect":{"iram":{"0x30":2,"0x31":0,"0x32":0,"0x40":0},"ports":{"P1":255,"P2":255}}}]},"hints":["Kiểm giới hạn TRƯỚC khi nhảy: CJNE A,#3,… đặt CY = 1 khi A &lt; 3. Số thiết bị sai mà vẫn nhảy theo bảng là chạy vào vùng mã bất kỳ.","JMP @A+DPTR nhảy tới DPTR + A. Mỗi mục của bảng nên dài bằng nhau: “MOV A,B” (2 byte) + “AJMP DRVn” (2 byte) = 4 byte, nên A = số thiết bị × 4 (hai lần RL A).","Mẫu đèn phải được cất ở chỗ khác trong lúc A dùng để tính chỉ số; mỗi mục bảng lấy lại rồi nhảy (không gọi) tới driver."],"why":"Bảng nhảy là cách “con trỏ hàm” của hợp ngữ: thêm thiết bị thứ tư chỉ cần thêm một mục bảng và sửa số giới hạn, ứng dụng không đổi. Đây là cách menu hay trình xử lý lệnh chọn hành động theo mã, và cũng là chỗ dễ hỏng nhất nếu quên kiểm giới hạn chỉ số."},{"t":"Hàng đợi vòng 8 byte, không quá 160 chu kỳ","d":"<p>Ứng dụng không chờ bus: nó đặt byte vào một <b>hàng đợi vòng<\/b> 8 byte ở <code>40H<\/code>–<code>47H<\/code>, driver lấy ra gửi sau. Trạng thái hàng đợi: <code>38H<\/code> = vị trí ghi kế tiếp (0–7, ô <code>40H + vị trí<\/code>), <code>39H<\/code> = số byte đang có (0–8), <code>3AH<\/code> = số byte đã bị bỏ vì hàng đợi đầy. Ô <code>30H<\/code> = số byte cần thêm (0–10), lấy lần lượt từ <code>50H<\/code>. Với mỗi byte: nếu đang có 8 byte thì bỏ byte đó và tăng <code>3AH<\/code>; nếu không thì ghi vào ô ở vị trí ghi, vị trí tăng 1 (sau 7 là 0), số byte tăng 1. Không đổi <code>30H<\/code> và các ô hàng đợi không được ghi. Chạy không quá <b>160 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>), mã không quá <b>50 byte<\/b>. Code mẫu đúng nhưng chậm (196 chu kỳ khi thêm 10 byte vào hàng đợi rỗng).<\/p><p>Ví dụ: hàng đợi rỗng (<code>38H = 39H = 3AH = 00H<\/code>), thêm 3 byte 11H 22H 33H → <code>40H<\/code>–<code>42H<\/code> = 11 22 33, <code>38H = 03H<\/code>, <code>39H = 03H<\/code>.<\/p>","start":"; Hàng đợi vòng 8 byte ở 40H..47H giữa ứng dụng và driver.\n; 38H = vị trí ghi kế tiếp (0..7), 39H = số byte đang có\n; (0..8), 3AH = số byte bị bỏ vì đầy. 30H = số byte cần\n; thêm, lấy lần lượt từ 50H. Đúng nhưng chậm.\n        ORG     0000H\n        MOV     R0,#50H\n        MOV     R2,30H\nLAP:    MOV     A,R2\n        JZ      XONG\n        MOV     A,39H\n        CJNE    A,#8,CO\n        INC     3AH                     ; đầy: bỏ byte\n        SJMP    TIEP\nCO:     MOV     A,38H\n        ADD     A,#40H\n        MOV     R1,A\n        MOV     A,@R0\n        MOV     @R1,A\n        INC     38H\n        MOV     A,38H\n        CJNE    A,#8,KQ\n        MOV     38H,#0                  ; quay vòng về 40H\nKQ:     INC     39H\nTIEP:   INC     R0\n        DEC     R2\n        SJMP    LAP\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x40":224,"0x41":225,"0x42":226,"0x43":227,"0x44":228,"0x45":229,"0x46":230,"0x47":231,"0x50":17,"0x51":34,"0x52":51,"0x30":3,"0x38":0,"0x39":0,"0x3A":0}},"expect":{"iram":{"0x40":17,"0x41":34,"0x42":51,"0x43":227,"0x44":228,"0x45":229,"0x46":230,"0x47":231,"0x30":3,"0x38":3,"0x39":3,"0x3A":0}}},{"setup":{"iram":{"0x40":224,"0x41":225,"0x42":226,"0x43":227,"0x44":228,"0x45":229,"0x46":230,"0x47":231,"0x30":0,"0x38":3,"0x39":3,"0x3A":0}},"expect":{"iram":{"0x40":224,"0x41":225,"0x42":226,"0x43":227,"0x44":228,"0x45":229,"0x46":230,"0x47":231,"0x30":0,"0x38":3,"0x39":3,"0x3A":0}}},{"setup":{"iram":{"0x40":224,"0x41":225,"0x42":226,"0x43":227,"0x44":228,"0x45":229,"0x46":230,"0x47":231,"0x50":161,"0x51":162,"0x52":163,"0x53":164,"0x30":4,"0x38":6,"0x39":2,"0x3A":0}},"expect":{"iram":{"0x40":163,"0x41":164,"0x42":226,"0x43":227,"0x44":228,"0x45":229,"0x46":161,"0x47":162,"0x30":4,"0x38":2,"0x39":6,"0x3A":0}}},{"setup":{"iram":{"0x40":224,"0x41":225,"0x42":226,"0x43":227,"0x44":228,"0x45":229,"0x46":230,"0x47":231,"0x50":97,"0x51":98,"0x52":99,"0x53":100,"0x54":101,"0x55":102,"0x56":103,"0x57":104,"0x58":105,"0x59":106,"0x30":10,"0x38":0,"0x39":0,"0x3A":0}},"expect":{"iram":{"0x40":97,"0x41":98,"0x42":99,"0x43":100,"0x44":101,"0x45":102,"0x46":103,"0x47":104,"0x30":10,"0x38":0,"0x39":8,"0x3A":2}}},{"setup":{"iram":{"0x40":224,"0x41":225,"0x42":226,"0x43":227,"0x44":228,"0x45":229,"0x46":230,"0x47":231,"0x50":1,"0x51":2,"0x52":3,"0x30":3,"0x38":4,"0x39":8,"0x3A":5}},"expect":{"iram":{"0x40":224,"0x41":225,"0x42":226,"0x43":227,"0x44":228,"0x45":229,"0x46":230,"0x47":231,"0x30":3,"0x38":4,"0x39":8,"0x3A":8}}},{"setup":{"iram":{"0x40":224,"0x41":225,"0x42":226,"0x43":227,"0x44":228,"0x45":229,"0x46":230,"0x47":231,"0x50":177,"0x51":178,"0x52":179,"0x53":180,"0x54":181,"0x30":5,"0x38":5,"0x39":6,"0x3A":0}},"expect":{"iram":{"0x40":224,"0x41":225,"0x42":226,"0x43":227,"0x44":228,"0x45":177,"0x46":178,"0x47":231,"0x30":5,"0x38":7,"0x39":8,"0x3A":3}}},{"setup":{"iram":{"0x40":224,"0x41":225,"0x42":226,"0x43":227,"0x44":228,"0x45":229,"0x46":230,"0x47":231,"0x50":192,"0x51":193,"0x52":194,"0x53":195,"0x54":196,"0x55":197,"0x56":198,"0x57":199,"0x30":8,"0x38":7,"0x39":0,"0x3A":1}},"expect":{"iram":{"0x40":193,"0x41":194,"0x42":195,"0x43":196,"0x44":197,"0x45":198,"0x46":199,"0x47":192,"0x30":8,"0x38":7,"0x39":8,"0x3A":1}}}],"maxCyc":160,"maxBytes":50},"hints":["Đọc vị trí và số byte vào hai thanh ghi một lần trước vòng lặp, ghi trả về RAM một lần sau vòng lặp: thao tác thanh ghi rẻ hơn thao tác ô nhớ trực tiếp.","Quay vòng 0…7 không cần so sánh: tăng rồi AND với 07H. Ô nhớ của R3 (bank 0) là 03H nên ANL 03H,#07H làm luôn trên thanh ghi.","Vị trí 0…7 cộng 40H bằng ORL A,#40H. Dùng DJNZ thay cho cặp DEC + kiểm 0 + SJMP; kiểm “không có byte nào” một lần trước vòng lặp."],"why":"Hàng đợi tách nhịp của ứng dụng khỏi nhịp của bus: ứng dụng đưa byte vào trong vài µs rồi đi làm việc khác, driver gửi khi bus rảnh (thường trong ngắt hoặc trong vòng lặp chính). Kích thước là lũy thừa của 2 để quay vòng bằng một phép AND. Hàng đợi đầy là chuyện phải tính trước: bỏ byte mới và đếm lại (như ở đây), bỏ byte cũ, hay bắt ứng dụng chờ — ghi rõ lựa chọn trong hợp đồng của driver."}]);

makeQuiz("quiz44","score44",[{"q": "Hợp đồng ghi “OUT8_WRITE: phá A, R7”. Ứng dụng giữ số đếm trong R7 qua lời gọi. Cách sửa nào đúng tinh thần tách lớp?", "o": ["Sửa SPI_XFER để dùng R7 của ứng dụng làm bộ đếm", "Không cần sửa vì R7 thường vẫn đúng", "Ứng dụng dùng thanh ghi không bị phá, hoặc driver đổi hợp đồng và cất R7 bằng PUSH/POP", "Gọi OUT8_WRITE hai lần liên tiếp"], "a": 2, "e": "Người gọi chỉ được tin vào hợp đồng. Hoặc tránh thanh ghi bị phá, hoặc driver giữ thanh ghi và ghi lại hợp đồng mới (ví dụ 5)."}, {"q": "Bo đổi từ 74HC595 (SPI) sang PCF8574 (I2C) cho 8 đèn. Với thiết kế ba lớp của bài, phải sửa gì?", "o": ["Thay driver OUT8 và lớp bus; ứng dụng giữ nguyên", "Sửa ứng dụng ở mọi chỗ ghi đèn", "Chỉ sửa dòng BIT của chân", "Không sửa gì, I2C và SPI giống nhau"], "a": 0, "e": "Linh kiện và bus đổi nên driver và bus đổi; giao diện OUT8_WRITE giữ nguyên nên ứng dụng không đổi (ví dụ 1 và 2). Sửa dòng BIT chỉ đủ khi đổi chân."}, {"q": "Ứng dụng gọi OUT8_WRITE bản I2C (155 µs ở 12 MHz) mỗi 1 ms. Việc cập nhật đèn chiếm bao nhiêu thời gian CPU?", "o": ["1,55 %", "155 %", "15,5 %", "0,155 %"], "a": 2, "e": "155 µs / 1 000 µs = 0,155 = 15,5 %."}, {"q": "Bảng nhảy có mỗi mục 4 byte (MOV A,B + AJMP). Số thiết bị là 2. Trước JMP @A+DPTR, A phải bằng bao nhiêu?", "o": ["02H", "04H", "06H", "08H"], "a": 3, "e": "Địa chỉ mục = BANG + số thiết bị × 4 = BANG + 8; A = 08H (hai lần RL A)."}, {"q": "Hàng đợi vòng 8 byte, vị trí ghi đang là 7. Ghi thêm một byte, vị trí ghi mới là bao nhiêu nếu tính bằng (vị trí + 1) AND 07H?", "o": ["8", "0", "7", "1"], "a": 1, "e": "(7 + 1) AND 07H = 08H AND 07H = 0: quay về đầu bộ đệm mà không cần so sánh. Chỉ đúng khi kích thước là lũy thừa của 2."}]);

